// Parity between src/plan.ts and the Python reference (blueprint-kit/tools/blueprintlib.py).
// fixtures.json.gz is generated by test/gen_fixtures.py from the Python code.
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { gunzipSync } from "node:zlib";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

import * as plan from "../src/plan.ts";

const here = dirname(fileURLToPath(import.meta.url));
const fx = JSON.parse(gunzipSync(readFileSync(join(here, "fixtures.json.gz"))).toString("utf-8"));

test("fixtures are present and large enough to mean something", () => {
  assert.ok(fx.glob_match.length >= 20);
  assert.ok(fx.overlap.length >= 600);
  assert.ok(fx.validate.length >= 300);
  assert.ok(fx.state.length >= 300);
  assert.ok(fx.waves.length >= 200);
});

test("glob matching agrees with Python", () => {
  for (const c of fx.glob_match) {
    c.patterns.forEach((pat: string, i: number) => {
      assert.equal(plan.matches(c.path, [pat]), c.expected[i], `${c.path} ~ ${pat}`);
    });
  }
});

test("path overlap agrees with Python (all pattern pairs)", () => {
  for (const c of fx.overlap) assert.equal(plan.mayOverlap(c.a, c.b), c.expected, `${c.a} ~ ${c.b}`);
});

test("validation errors and warnings are identical (base, example and seeded mutations)", () => {
  let withErrors = 0;
  let withWarnings = 0;
  for (const c of fx.validate) {
    const r = plan.validate(c.cells, c.cfg);
    assert.deepEqual(r.errors, c.errors, `errors differ in ${c.label}`);
    assert.deepEqual(r.warnings, c.warnings, `warnings differ in ${c.label}`);
    if (c.errors.length) withErrors++;
    if (c.warnings.length) withWarnings++;
  }
  // the fuzz must exercise both outcomes, otherwise the test proves little
  assert.ok(withErrors > 100, `only ${withErrors} cases with errors`);
  assert.ok(withWarnings > 20, `only ${withWarnings} cases with warnings`);
  const clean = fx.validate.filter((c: any) => !c.errors.length).length;
  assert.ok(clean > 20, `only ${clean} clean cases`);
});

test("supersedes errors and warnings are exercised by the validation fixtures", () => {
  const all = fx.validate.flatMap((c: any) => [...c.errors, ...c.warnings]);
  for (const part of ["supersedes: unknown cell", "supersedes: a cell cannot supersede itself", "supersedes cycle:", "'supersedes' must be a list of strings", "superseded, but no superseder provides"]) {
    assert.ok(all.some((m: string) => m.includes(part)), `never exercised: ${part}`);
  }
  assert.ok(fx.validate.some((c: any) => Object.values(c.cells).some((x: any) => Array.isArray(x.supersedes) && x.supersedes.length) && !c.errors.length), "no clean supersedes case");
});

test("waves agree with Python", () => {
  for (const c of fx.waves) assert.deepEqual(plan.waves(c.cells), c.expected);
});

test("readiness state and rendered text agree with Python", () => {
  const seen = new Set<string>();
  for (const c of fx.state) {
    const st = plan.computeState(c.cells, c.merged, c.claims, c.lease, c.ci, 45, c.threshold, {
      criticalChainThreshold: c.options.critical_chain_threshold,
      criticalTransitiveThreshold: c.options.critical_transitive_threshold,
      criticalLeaseMinutes: c.options.critical_lease_minutes,
      parkMaxMinutes: c.options.park_max_minutes,
      released: c.released,
      attempts: c.attempts,
      maxAttempts: c.max_attempts,
      feedback: c.feedback,
    });
    assert.deepEqual(JSON.parse(JSON.stringify(st)), c.expected);
    assert.equal(plan.render(st), c.render);
    assert.equal(plan.render(st, 3), c.render3);
    seen.add(st.status);
  }
  assert.deepEqual([...seen].sort(), ["all_done", "none_ready", "ready"]);
  assert.ok(fx.state.some((c: any) => c.render.includes("(CI<=")), "CI-locked rendering never exercised");
  assert.ok(fx.state.some((c: any) => c.render.includes("[critical]")), "critical flag never exercised");
  assert.ok(fx.state.some((c: any) => c.render.includes("expired-lease")), "reclaim never exercised");
  assert.ok(fx.state.some((c: any) => c.render.includes("(released)")), "release never exercised");
  assert.ok(fx.state.some((c: any) => c.expected.ready.some((r: any) => r.released)), "released flag never exercised");
  assert.ok(fx.state.some((c: any) => c.released.length && c.ci && Object.keys(c.ci).some((k) => c.released.includes(k))), "release over CI never exercised");
  assert.ok(fx.state.some((c: any) => Object.values(c.cells).some((x: any) => x.type === "skeleton") && c.expected.ready.some((r: any) => r.critical && c.cells[r.id].type === "skeleton")), "critical skeleton never exercised");
  assert.ok(fx.state.some((c: any) => c.expected.ready.some((r: any) => r.reclaim && !r.critical && c.claims[r.id] >= c.options.park_max_minutes)), "parked-old class never exercised");
  assert.ok(fx.state.some((c: any) => c.expected.ready.some((r: any) => r.reclaim && !r.critical && c.claims[r.id] < c.options.park_max_minutes)), "parked-young class never exercised");
  assert.ok(fx.state.some((c: any) => c.expected.needs_split), "needs_split never exercised");
  assert.ok(fx.state.some((c: any) => c.expected.needs_human), "needs_human never exercised");
  assert.ok(fx.state.some((c: any) => c.render.includes("A human must resolve the cells above.")), "human-only ending never exercised");
  assert.ok(fx.state.some((c: any) => c.expected.status !== "ready" && c.render.includes("needs_") && !c.render.includes("A human")), "needs_* next to running cells never exercised");
  assert.ok(fx.state.some((c: any) => c.render.startsWith("READY") && c.render.includes("needs_")), "needs_* in a READY render never exercised");
  assert.ok(fx.state.some((c: any) => Object.values(c.cells).some((x: any) => x.supersedes) && c.expected.waiting.length), "supersedes waiting never exercised");
  assert.ok(fx.state.some((c: any) => c.max_attempts !== 3), "max_attempts never varied");
});

test("active workflow runs are parsed like Python", () => {
  for (const c of fx.runs) {
    const got = plan.parseRuns(c.runs, c.now_ms);
    assert.deepEqual(Object.keys(got).sort(), Object.keys(c.expected).sort());
    for (const k of Object.keys(got)) assert.ok(Math.abs(got[k] - c.expected[k]) < 1e-6, `${k}: ${got[k]} vs ${c.expected[k]}`);
  }
});

test("YAML 1.1 parsing agrees with PyYAML safe_load", () => {
  for (const c of fx.yaml) {
    if (c.error) {
      assert.throws(() => plan.loadCells({ "C-001.yaml": c.text }).cells["C-001"] ?? (() => { throw new Error("x"); })());
      continue;
    }
    const { cells } = plan.loadCells({ "C-001.yaml": c.text });
    if (c.value && typeof c.value === "object" && !Array.isArray(c.value)) {
      const want = { ...c.value, id: "C-001" };
      assert.deepEqual(cells["C-001"], want, c.text.slice(0, 40));
    }
  }
});

test("merged cells are read from commit subjects like Python", () => {
  const c = fx.subjects[0];
  assert.deepEqual([...plan.mergedFromSubjects(c.subjects)].sort(), c.expected);
});
